-- A copy of Core.ClientLifecycle.validate (classic source lines 3 to 16).
local function lifecycleValidate(entries)
	local index, visiting, visited = {}, {}, {}
	for _, entry in ipairs(entries) do
		assert(not index[entry.name], "Duplicate client " .. entry.name)
		index[entry.name] = entry
	end
	local function visit(name)
		assert(index[name], "Missing dependency " .. name)
		assert(not visiting[name], "Dependency cycle at " .. name)
		if visited[name] then
			return
		end
		visiting[name] = true
		for _, dependency in ipairs(index[name].dependencies or {}) do
			visit(dependency)
		end
		visiting[name] = nil
		visited[name] = true
	end
	for name in pairs(index) do
		visit(name)
	end
	return index
end

