	end
	local function snapshot(list)
		local lines = {}
		for index, entry in ipairs(list) do
			lines[index] = tostring(entry.name) .. "|" .. tostring(entry.path) .. "|" .. table.concat(entry.dependencies or {}, ",") .. "|" .. tostring(entry.tool)
		end
		return table.concat(lines, "\n")
	end
	local function fakeSwitch(style, dev)
		local switch = { Style = style, Commits = {} }
		local devSet = nil
		if dev then
			devSet = {}
			for _, family in ipairs(dev) do
				devSet[family] = true
			end
		end
		function switch.Active(family)
			return switch.Style == "Pulse" and (devSet == nil or devSet[family] == true)
		end
		function switch.Commit(report)
			switch.Commits[#switch.Commits + 1] = report
		end
		function switch.Report()
			return { Style = switch.Style, DevFamilies = dev }
		end
